// Server only. The kickoff deposit, using PayPal's official Server SDK (@paypal/paypal-server-sdk,
// generated by APIMatic). Written with the APIMatic Context Plugin skills for this SDK
// (typescript-getting-started, typescript-error-handling): one Client, controllers per API area,
// ApiResponse<T>.result for data, ApiError for every failed call.
//
// Flow: create an order with intent AUTHORIZE -> the client approves it at PayPal -> authorize
// (PayPal holds the funds) -> capture when the first phase is delivered, or void to release.

import {
  ApiError,
  CheckoutPaymentIntent,
  Client,
  Environment,
  OrdersController,
  PaymentsController,
  PaypalExperienceLandingPage,
  PaypalExperienceUserAction,
  PaypalWalletContextShippingPreference,
} from "@paypal/paypal-server-sdk";
import type { OrderRequest } from "@paypal/paypal-server-sdk";

let cached: { orders: OrdersController; payments: PaymentsController } | null = null;

function sdk() {
  if (cached) return cached;
  const oAuthClientId = process.env.PAYPAL_CLIENT_ID;
  const oAuthClientSecret = process.env.PAYPAL_CLIENT_SECRET;
  if (!oAuthClientId || !oAuthClientSecret) throw new OrderError("NOT_CONFIGURED", "PayPal sandbox credentials are not set on the server.", 500);
  const client = new Client({
    clientCredentialsAuthCredentials: { oAuthClientId, oAuthClientSecret },
    environment: Environment.Sandbox,
    timeout: 20_000,
  });
  cached = { orders: new OrdersController(client), payments: new PaymentsController(client) };
  return cached;
}

export class OrderError extends Error {
  issue: string;
  status: number;
  constructor(issue: string, message: string, status = 502) {
    super(message);
    this.issue = issue;
    this.status = status;
  }
}

/** Turn the SDK's ApiError into one error with PayPal's issue code. Anything else is a bug: rethrow. */
function fail(err: unknown): never {
  if (err instanceof ApiError) {
    const body = (err.result ?? {}) as { name?: string; message?: string; details?: { issue?: string; description?: string }[] };
    const issue = body.details?.[0]?.issue ?? body.name ?? "ERROR";
    const text = body.details?.[0]?.description ?? body.message ?? err.message;
    throw new OrderError(issue, `PayPal ${err.statusCode} ${issue}: ${text}`, err.statusCode >= 500 ? 502 : 400);
  }
  throw err;
}

export interface HoldOrder {
  orderId: string;
  status: string;
  approveUrl?: string;
}

export async function createHoldOrder(o: {
  requestId: string;
  amount: string;
  description: string;
  reference: string;
  brand: string;
  returnUrl: string;
  cancelUrl: string;
}): Promise<HoldOrder> {
  const body: OrderRequest = {
    intent: CheckoutPaymentIntent.Authorize,
    purchaseUnits: [
      {
        referenceId: o.reference,
        description: o.description.slice(0, 120),
        customId: o.reference,
        amount: { currencyCode: "USD", value: o.amount },
      },
    ],
    paymentSource: {
      paypal: {
        experienceContext: {
          brandName: o.brand,
          shippingPreference: PaypalWalletContextShippingPreference.NoShipping,
          landingPage: PaypalExperienceLandingPage.Login,
          userAction: PaypalExperienceUserAction.PayNow,
          returnUrl: o.returnUrl,
          cancelUrl: o.cancelUrl,
        },
      },
    },
  };
  try {
    const { result } = await sdk().orders.createOrder({ body, paypalRequestId: o.requestId, prefer: "return=representation" });
    const link = result.links?.find((l) => l.rel === "payer-action") ?? result.links?.find((l) => l.rel === "approve");
    if (!result.id) throw new OrderError("NO_ORDER_ID", "PayPal did not return an order id.");
    return { orderId: result.id, status: String(result.status ?? "CREATED"), approveUrl: link?.href };
  } catch (err) {
    return fail(err);
  }
}

export async function getOrderStatus(orderId: string): Promise<{ status: string; authorizationId?: string }> {
  try {
    const { result } = await sdk().orders.getOrder({ id: orderId });
    return {
      status: String(result.status ?? "UNKNOWN"),
      authorizationId: result.purchaseUnits?.[0]?.payments?.authorizations?.[0]?.id,
    };
  } catch (err) {
    return fail(err);
  }
}

/** After the client approved: place the hold. Returns PayPal's authorization id. */
export async function authorizeHold(orderId: string): Promise<{ authorizationId: string; status: string }> {
  try {
    const { result } = await sdk().orders.authorizeOrder({ id: orderId, paypalRequestId: `auth-${orderId}`, prefer: "return=representation" });
    const auth = result.purchaseUnits?.[0]?.payments?.authorizations?.[0];
    if (!auth?.id) throw new OrderError("NO_AUTHORIZATION", "PayPal did not return an authorization for this order.");
    return { authorizationId: auth.id, status: String(auth.status ?? "CREATED") };
  } catch (err) {
    return fail(err);
  }
}

/** Take the held funds. */
export async function captureHold(authorizationId: string, note: string): Promise<{ captureId: string; status: string }> {
  try {
    const { result } = await sdk().payments.captureAuthorizedPayment({
      authorizationId,
      paypalRequestId: `cap-${authorizationId}`,
      prefer: "return=representation",
      body: { finalCapture: true, noteToPayer: note.slice(0, 250) },
    });
    if (!result.id) throw new OrderError("NO_CAPTURE", "PayPal did not return a capture id.");
    return { captureId: result.id, status: String(result.status ?? "COMPLETED") };
  } catch (err) {
    return fail(err);
  }
}

/** Release the held funds without taking them. */
export async function voidHold(authorizationId: string): Promise<void> {
  try {
    await sdk().payments.voidPayment({ authorizationId, paypalRequestId: `void-${authorizationId}` });
  } catch (err) {
    fail(err);
  }
}
